DROP TABLE IF EXISTS public.vw_cbas_contr_history;

CREATE TABLE public.vw_cbas_contr_history (
	id text NULL, -- ИД записи в истории
	create_ts timestamp NULL, -- Дата и время создания
	contract_id text NULL, -- ИД объекта CBAS ctr_id
	verification_step text NULL, -- Шаг проверки
	records_id text NULL, -- Записи истории: реквизит id поля records типа json
	records_key text NULL, -- Записи истории: реквизит key поля records типа json
	records_val text NULL, -- Записи истории: реквизит val поля records типа json
	records_leaderrecord text NULL -- Записи истории: реквизит leaderRecord(тип json) поля records типа json
);
COMMENT ON TABLE public.vw_cbas_contr_history IS 'Представление, содержащее в себе историю обработки по объектам';

-- Column comments

COMMENT ON COLUMN public.vw_cbas_contr_history.id IS 'ИД записи в истории';
COMMENT ON COLUMN public.vw_cbas_contr_history.create_ts IS 'Дата и время создания';
COMMENT ON COLUMN public.vw_cbas_contr_history.contract_id IS 'ИД объекта CBAS ctr_id';
COMMENT ON COLUMN public.vw_cbas_contr_history.verification_step IS 'Шаг проверки';
COMMENT ON COLUMN public.vw_cbas_contr_history.records_id IS 'Записи истории: реквизит id поля records типа json';
COMMENT ON COLUMN public.vw_cbas_contr_history.records_key IS 'Записи истории: реквизит key поля records типа json';
COMMENT ON COLUMN public.vw_cbas_contr_history.records_val IS 'Записи истории: реквизит val поля records типа json';
COMMENT ON COLUMN public.vw_cbas_contr_history.records_leaderrecord IS 'Записи истории: реквизит leaderRecord(тип json) поля records типа json';


